import{_ as t,a as r,c as d,ac as a}from"./chunks/framework.BSuaGltH.js";const b=JSON.parse('{"title":"Redis Stream（消息流） · 2. 命令速查与示例","description":"事件记录、消费组与比赛结果入库，包括基本操作、适用场景和使用边界。","frontmatter":{"title":"Redis Stream（消息流） · 2. 命令速查与示例","description":"事件记录、消费组与比赛结果入库，包括基本操作、适用场景和使用边界。","splitFrom":"middleware/redis/plus/subjects/stream.md","showdocs":{"topics":[{"id":"redis","title":"Redis","link":"/topics/redis/"}],"kind":"数据与原子性","scope":"general","audience":"general","group":"数据库与存储","seriesTitle":"Redis Stream（消息流）","summary":"事件记录、消费组与比赛结果入库，包括基本操作、适用场景和使用边界。","status":"active","related":[{"title":"Redis 操作与命令","link":"/middleware/redis/plus/ecosystem/redis-general-general","kind":"数据与原子性","scope":"general","audience":"general"},{"title":"Redis 数据类型命令速查","link":"/middleware/redis/plus/subjects/redis-data-cmd","kind":"数据与原子性","scope":"general","audience":"general"},{"title":"Redis 完整实践：Lua 原子限额与可重试 CLI","link":"/middleware/redis/plus/practice/quota","kind":"完整实践","scope":"general","audience":"general"},{"title":"Redis 游戏与通用后端场景","link":"/middleware/redis/pro/practice/game-scenarios","kind":"完整实践","scope":"general","audience":"general"},{"title":"Redis 持久化：RDB、AOF 与独立恢复","link":"/middleware/redis/persistence-and-recovery","kind":"数据与原子性","scope":"general","audience":"general"}],"prev":{"text":"Redis Stream（消息流） · 1. 定位：解决什么问题","link":"/middleware/redis/plus/subjects/stream-part-01"},"next":{"text":"Redis Stream（消息流） · 3. 底层编码与内存至8. Go 客户端与最佳实践","link":"/middleware/redis/plus/subjects/stream-part-03"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"Redis Stream（消息流） · 1. 定位：解决什么问题","link":"/middleware/redis/plus/subjects/stream-part-01"},"next":{"text":"Redis Stream（消息流） · 3. 底层编码与内存至8. Go 客户端与最佳实践","link":"/middleware/redis/plus/subjects/stream-part-03"}},"headers":[],"relativePath":"middleware/redis/plus/subjects/stream-part-02.md","filePath":"middleware/redis/plus/subjects/stream-part-02.md"}'),s={name:"middleware/redis/plus/subjects/stream-part-02.md"};function n(o,e,i,c,l,m){return r(),d("div",null,[...e[0]||(e[0]=[a(`<h1 id="redis-stream-消息流-·-2-命令速查与示例" tabindex="-1">Redis Stream（消息流） · 2. 命令速查与示例 <a class="header-anchor" href="#redis-stream-消息流-·-2-命令速查与示例" aria-label="Permalink to &quot;Redis Stream（消息流） · 2. 命令速查与示例&quot;">​</a></h1><p><a href="/middleware/redis/plus/subjects/stream">返回分篇目录</a></p><p>本文按 Redis 8.2.10 核对编码与配置默认值；命令的引入版本另行标注。生产配置可能不同，可通过 CONFIG GET 查询。示例面向独立实验服务，运行结果和内存数字未在本次实测。</p><h2 id="commands" tabindex="-1">2. 命令速查与示例 <a class="header-anchor" href="#commands" aria-label="Permalink to &quot;2. 命令速查与示例 {#commands}&quot;">​</a></h2><p>按用途分组，共 <strong>27 项</strong>，覆盖 Redis 8.2.10 的本类型命令及子命令。点击命令名查看官方参数。示例在 redis-cli 中逐行输入，<strong>每次换例子前重置下面的教学数据</strong>。</p><details class="details custom-block"><summary>准备与重置示例数据</summary><p>在独立实验实例的 <strong>redis-cli 交互模式</strong>逐行输入，避免 shell 对引号、<code>&gt;</code>、<code>*</code>、括号等符号进行解释。<strong>每个例子独立使用；换例子前重新执行下面的准备段</strong>，否则删除、弹出、过期和修改操作会影响后续结果。准备段仅重置列出的教学键，确认这些键不承载业务数据。</p><div class="language-text vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>UNLINK learn:{stream}:events</span></span>
<span class="line"><span>XADD learn:{stream}:events 1-0 action login uid 42</span></span>
<span class="line"><span>XADD learn:{stream}:events 2-0 action score uid 42</span></span>
<span class="line"><span>XADD learn:{stream}:events 3-0 action logout uid 42</span></span>
<span class="line"><span>XGROUP CREATE learn:{stream}:events readers 0</span></span>
<span class="line"><span>XREADGROUP GROUP readers alice COUNT 2 STREAMS learn:{stream}:events &gt;</span></span></code></pre></div><p>示例的返回说明以刚完成准备段为前提，随机结果与剩余 TTL 不固定。带同一 <code>{...}</code> 的教学键便于在 Cluster 中满足相关多键操作的同槽要求。</p></details><h3 id="写入、读取与裁剪" tabindex="-1">写入、读取与裁剪 <a class="header-anchor" href="#写入、读取与裁剪" aria-label="Permalink to &quot;写入、读取与裁剪 {#写入、读取与裁剪}&quot;">​</a></h3><table tabindex="0"><thead><tr><th>命令与用途</th><th>示例与结果</th><th>复杂度</th></tr></thead><tbody><tr><td><span id="cmd-xadd"></span><a href="https://github.com/redis/redis/blob/8.2.10/src/commands/xadd.json" target="_blank" rel="noopener noreferrer">XADD</a><br>追加事件</td><td><code>XADD learn:{stream}:events * action score uid 42</code><br>返回新 ID，具体值随执行时刻变化。</td><td>追加 O(1)<br>裁剪 O(R)</td></tr><tr><td><span id="cmd-xlen"></span><a href="https://github.com/redis/redis/blob/8.2.10/src/commands/xlen.json" target="_blank" rel="noopener noreferrer">XLEN</a><br>流的条目数</td><td><code>XLEN learn:{stream}:events</code><br>准备数据中有 3 条，返回 3。</td><td>O(1)</td></tr><tr><td><span id="cmd-xrange"></span><a href="https://github.com/redis/redis/blob/8.2.10/src/commands/xrange.json" target="_blank" rel="noopener noreferrer">XRANGE</a><br>正序读取区间</td><td><code>XRANGE learn:{stream}:events - + COUNT 2</code><br>返回 1-0、2-0 两条。</td><td>O(M)</td></tr><tr><td><span id="cmd-xrevrange"></span><a href="https://github.com/redis/redis/blob/8.2.10/src/commands/xrevrange.json" target="_blank" rel="noopener noreferrer">XREVRANGE</a><br>倒序读取区间</td><td><code>XREVRANGE learn:{stream}:events + - COUNT 2</code><br>返回 3-0、2-0。</td><td>O(M)</td></tr><tr><td><span id="cmd-xread"></span><a href="https://github.com/redis/redis/blob/8.2.10/src/commands/xread.json" target="_blank" rel="noopener noreferrer">XREAD</a><br>按游标读取</td><td><code>XREAD COUNT 2 STREAMS learn:{stream}:events 0-0</code><br>返回前两条；BLOCK 等待时使用有限超时。</td><td>随流数、返回量变化</td></tr><tr><td><span id="cmd-xdel"></span><a href="https://github.com/redis/redis/blob/8.2.10/src/commands/xdel.json" target="_blank" rel="noopener noreferrer">XDEL</a><br>删除指定条目</td><td><code>XDEL learn:{stream}:events 3-0</code><br>返回 1；旧待确认引用可能仍需处理。</td><td>每个指定 ID O(1)</td></tr><tr><td><span id="cmd-xdelex"></span><a href="https://github.com/redis/redis/blob/8.2.10/src/commands/xdelex.json" target="_blank" rel="noopener noreferrer">XDELEX</a><br>按引用策略删除</td><td><code>XDELEX learn:{stream}:events DELREF IDS 1 2-0</code><br>8.2 起可用；DELREF 删除正文及引用，不能当作处理成功确认。</td><td>每个指定 ID O(1)</td></tr><tr><td><span id="cmd-xtrim"></span><a href="https://github.com/redis/redis/blob/8.2.10/src/commands/xtrim.json" target="_blank" rel="noopener noreferrer">XTRIM</a><br>裁剪历史</td><td><code>XTRIM learn:{stream}:events MAXLEN = 2</code><br>精确保留 2 条；裁剪和待确认记录需配合保留策略。</td><td>O(R)</td></tr></tbody></table><h3 id="消费与确认" tabindex="-1">消费与确认 <a class="header-anchor" href="#消费与确认" aria-label="Permalink to &quot;消费与确认 {#消费与确认}&quot;">​</a></h3><table tabindex="0"><thead><tr><th>命令与用途</th><th>示例与结果</th><th>复杂度</th></tr></thead><tbody><tr><td><span id="cmd-xreadgroup"></span><a href="https://github.com/redis/redis/blob/8.2.10/src/commands/xreadgroup.json" target="_blank" rel="noopener noreferrer">XREADGROUP</a><br>消费组读取新消息</td><td><code>XREADGROUP GROUP readers bob COUNT 1 STREAMS learn:{stream}:events &gt;</code><br>前两条已由 alice 领取，bob 得到 3-0。</td><td>每条流 O(M)</td></tr><tr><td><span id="cmd-xpending"></span><a href="https://github.com/redis/redis/blob/8.2.10/src/commands/xpending.json" target="_blank" rel="noopener noreferrer">XPENDING</a><br>查看待确认记录</td><td><code>XPENDING learn:{stream}:events readers - + 10</code><br>准备数据中包含 alice 的 1-0、2-0。</td><td>随返回/扫描量变化</td></tr><tr><td><span id="cmd-xack"></span><a href="https://github.com/redis/redis/blob/8.2.10/src/commands/xack.json" target="_blank" rel="noopener noreferrer">XACK</a><br>确认处理完成</td><td><code>XACK learn:{stream}:events readers 1-0</code><br>确认数为 1，不删除正文。</td><td>每个指定 ID O(1)</td></tr><tr><td><span id="cmd-xackdel"></span><a href="https://github.com/redis/redis/blob/8.2.10/src/commands/xackdel.json" target="_blank" rel="noopener noreferrer">XACKDEL</a><br>确认并按策略删除</td><td><code>XACKDEL learn:{stream}:events readers DELREF IDS 1 1-0</code><br>8.2 起可用；同时删除相关引用，必须在业务成功后使用。</td><td>每个指定 ID O(1)</td></tr><tr><td><span id="cmd-xclaim"></span><a href="https://github.com/redis/redis/blob/8.2.10/src/commands/xclaim.json" target="_blank" rel="noopener noreferrer">XCLAIM</a><br>指定 ID 接管</td><td><code>XCLAIM learn:{stream}:events readers bob 0 2-0</code><br>演示立即接管 alice 的待处理消息；生产应设置合理空闲阈值。</td><td>O(log P)</td></tr><tr><td><span id="cmd-xautoclaim"></span><a href="https://github.com/redis/redis/blob/8.2.10/src/commands/xautoclaim.json" target="_blank" rel="noopener noreferrer">XAUTOCLAIM</a><br>游标接管超时消息</td><td><code>XAUTOCLAIM learn:{stream}:events readers bob 0 0-0 COUNT 10</code><br>返回继续游标和接管条目；0 空闲阈值仅为演示。</td><td>小 COUNT 时 O(1)</td></tr></tbody></table><h3 id="消费组子命令" tabindex="-1">消费组子命令 <a class="header-anchor" href="#消费组子命令" aria-label="Permalink to &quot;消费组子命令 {#消费组子命令}&quot;">​</a></h3><table tabindex="0"><thead><tr><th>命令与用途</th><th>示例与结果</th><th>复杂度</th></tr></thead><tbody><tr><td><span id="cmd-xgroup"></span><a href="https://github.com/redis/redis/blob/8.2.10/src/commands/xgroup.json" target="_blank" rel="noopener noreferrer">XGROUP</a><br>消费组命令入口</td><td><code>XGROUP HELP</code><br>必须指定子命令，本例列出可用操作。</td><td>取决于子命令</td></tr><tr><td><span id="cmd-xgroup-create"></span><a href="https://github.com/redis/redis/blob/8.2.10/src/commands/xgroup-create.json" target="_blank" rel="noopener noreferrer">XGROUP CREATE</a><br>创建消费组</td><td><code>XGROUP CREATE learn:{stream}:events audit 0</code><br>创建另一个 audit 组，从历史起点开始。</td><td>O(1)</td></tr><tr><td><span id="cmd-xgroup-createconsumer"></span><a href="https://github.com/redis/redis/blob/8.2.10/src/commands/xgroup-createconsumer.json" target="_blank" rel="noopener noreferrer">XGROUP CREATECONSUMER</a><br>创建消费者</td><td><code>XGROUP CREATECONSUMER learn:{stream}:events readers bob</code><br>首次创建返回 1。</td><td>O(1)</td></tr><tr><td><span id="cmd-xgroup-delconsumer"></span><a href="https://github.com/redis/redis/blob/8.2.10/src/commands/xgroup-delconsumer.json" target="_blank" rel="noopener noreferrer">XGROUP DELCONSUMER</a><br>移除消费者</td><td><code>XGROUP DELCONSUMER learn:{stream}:events readers alice</code><br>移除 alice 及其待处理记录；先处理未完成消息，不用于正常确认。</td><td>O(1)</td></tr><tr><td><span id="cmd-xgroup-destroy"></span><a href="https://github.com/redis/redis/blob/8.2.10/src/commands/xgroup-destroy.json" target="_blank" rel="noopener noreferrer">XGROUP DESTROY</a><br>销毁消费组</td><td><code>XGROUP DESTROY learn:{stream}:events readers</code><br>删除组和其待确认状态，正文仍保留。</td><td>O(P)</td></tr><tr><td><span id="cmd-xgroup-setid"></span><a href="https://github.com/redis/redis/blob/8.2.10/src/commands/xgroup-setid.json" target="_blank" rel="noopener noreferrer">XGROUP SETID</a><br>调整消费组游标</td><td><code>XGROUP SETID learn:{stream}:events readers 0</code><br>只修改投递游标，可能重读历史，不自动清空 PEL。</td><td>O(1)</td></tr><tr><td><span id="cmd-xgroup-help"></span><a href="https://github.com/redis/redis/blob/8.2.10/src/commands/xgroup-help.json" target="_blank" rel="noopener noreferrer">XGROUP HELP</a><br>查看消费组帮助</td><td><code>XGROUP HELP</code><br>返回子命令用法。</td><td>O(1)</td></tr></tbody></table><h3 id="信息查询与内部管理" tabindex="-1">信息查询与内部管理 <a class="header-anchor" href="#信息查询与内部管理" aria-label="Permalink to &quot;信息查询与内部管理 {#信息查询与内部管理}&quot;">​</a></h3><table tabindex="0"><thead><tr><th>命令与用途</th><th>示例与结果</th><th>复杂度</th></tr></thead><tbody><tr><td><span id="cmd-xinfo"></span><a href="https://github.com/redis/redis/blob/8.2.10/src/commands/xinfo.json" target="_blank" rel="noopener noreferrer">XINFO</a><br>流信息命令入口</td><td><code>XINFO HELP</code><br>必须指定子命令。</td><td>取决于子命令</td></tr><tr><td><span id="cmd-xinfo-stream"></span><a href="https://github.com/redis/redis/blob/8.2.10/src/commands/xinfo-stream.json" target="_blank" rel="noopener noreferrer">XINFO STREAM</a><br>流概要</td><td><code>XINFO STREAM learn:{stream}:events</code><br>显示长度、首尾条目等信息。</td><td>普通概要 O(1)</td></tr><tr><td><span id="cmd-xinfo-groups"></span><a href="https://github.com/redis/redis/blob/8.2.10/src/commands/xinfo-groups.json" target="_blank" rel="noopener noreferrer">XINFO GROUPS</a><br>消费组状态</td><td><code>XINFO GROUPS learn:{stream}:events</code><br>显示 readers 等组的信息。</td><td>O(G)</td></tr><tr><td><span id="cmd-xinfo-consumers"></span><a href="https://github.com/redis/redis/blob/8.2.10/src/commands/xinfo-consumers.json" target="_blank" rel="noopener noreferrer">XINFO CONSUMERS</a><br>消费者状态</td><td><code>XINFO CONSUMERS learn:{stream}:events readers</code><br>显示 alice 的待处理和空闲情况。</td><td>O(C)</td></tr><tr><td><span id="cmd-xinfo-help"></span><a href="https://github.com/redis/redis/blob/8.2.10/src/commands/xinfo-help.json" target="_blank" rel="noopener noreferrer">XINFO HELP</a><br>查看信息命令帮助</td><td><code>XINFO HELP</code><br>返回子命令用法。</td><td>O(1)</td></tr><tr><td><span id="cmd-xsetid"></span><a href="https://github.com/redis/redis/blob/8.2.10/src/commands/xsetid.json" target="_blank" rel="noopener noreferrer">XSETID</a><br>设置流的内部末尾 ID</td><td><code>XSETID learn:{stream}:events 10-0</code><br>内部管理用途，通常由复制/恢复流程使用；不要用于普通事件生产。</td><td>O(1)</td></tr></tbody></table><details class="details custom-block"><summary>版本与复杂度补充</summary><p>下表保留每条命令的引入版本、兼容状态及复杂度符号含义；复杂度不包含全部网络传输、内存分配和等待成本。</p><table tabindex="0"><thead><tr><th>命令</th><th>引入版本与状态</th><th>复杂度说明</th></tr></thead><tbody><tr><td><a href="/middleware/redis/plus/subjects/stream-part-02#cmd-xadd">XADD</a></td><td>5.0.0</td><td>普通追加 O(1)，附带裁剪另计 O(R)；唤醒阻塞读者也有额外工作。</td></tr><tr><td><a href="/middleware/redis/plus/subjects/stream-part-02#cmd-xlen">XLEN</a></td><td>5.0.0</td><td>O(1)。大值复制、扩容、网络输出和等待时间需另外考虑。</td></tr><tr><td><a href="/middleware/redis/plus/subjects/stream-part-02#cmd-xrange">XRANGE</a></td><td>5.0.0</td><td>O(M)，M 为返回条目数；固定 COUNT 时可看作常数上界。</td></tr><tr><td><a href="/middleware/redis/plus/subjects/stream-part-02#cmd-xrevrange">XREVRANGE</a></td><td>5.0.0</td><td>O(M)，M 为返回条目数；固定 COUNT 时可看作常数上界。</td></tr><tr><td><a href="/middleware/redis/plus/subjects/stream-part-02#cmd-xread">XREAD</a></td><td>5.0.0</td><td>8.2.10 定义未单列复杂度；实际工作随流数和返回条目数变化，等待时间另计。</td></tr><tr><td><a href="/middleware/redis/plus/subjects/stream-part-02#cmd-xdel">XDEL</a></td><td>5.0.0</td><td>每个指定 ID O(1)，K 个 ID 为 O(K)。</td></tr><tr><td><a href="/middleware/redis/plus/subjects/stream-part-02#cmd-xdelex">XDELEX</a></td><td>8.2.0</td><td>每个指定 ID O(1)，K 个 ID 为 O(K)。</td></tr><tr><td><a href="/middleware/redis/plus/subjects/stream-part-02#cmd-xtrim">XTRIM</a></td><td>5.0.0</td><td>O(R)，R 为实际移除元素数。</td></tr><tr><td><a href="/middleware/redis/plus/subjects/stream-part-02#cmd-xreadgroup">XREADGROUP</a></td><td>5.0.0</td><td>每条流 O(M)，M 为返回消息数；服务被唤醒的阻塞读者会增加生产者工作。</td></tr><tr><td><a href="/middleware/redis/plus/subjects/stream-part-02#cmd-xpending">XPENDING</a></td><td>5.0.0</td><td>明细随返回数变化；IDLE 过滤还随扫描数变化；摘要受消费者数量影响。</td></tr><tr><td><a href="/middleware/redis/plus/subjects/stream-part-02#cmd-xack">XACK</a></td><td>5.0.0</td><td>每个指定 ID O(1)，K 个 ID 为 O(K)。</td></tr><tr><td><a href="/middleware/redis/plus/subjects/stream-part-02#cmd-xackdel">XACKDEL</a></td><td>8.2.0</td><td>每个指定 ID O(1)，K 个 ID 为 O(K)。</td></tr><tr><td><a href="/middleware/redis/plus/subjects/stream-part-02#cmd-xclaim">XCLAIM</a></td><td>5.0.0</td><td>O(log P)，P 为消费组待处理条目数；批量 ID 增加工作量。</td></tr><tr><td><a href="/middleware/redis/plus/subjects/stream-part-02#cmd-xautoclaim">XAUTOCLAIM</a></td><td>6.2.0</td><td>小 COUNT 时 O(1)；一次扫描工作受 COUNT 限制，需用游标继续。</td></tr><tr><td><a href="/middleware/redis/plus/subjects/stream-part-02#cmd-xgroup">XGROUP</a></td><td>5.0.0</td><td>取决于所调用的子命令，入口本身不能独立执行。</td></tr><tr><td><a href="/middleware/redis/plus/subjects/stream-part-02#cmd-xgroup-create">XGROUP CREATE</a></td><td>5.0.0</td><td>O(1)。大值复制、扩容、网络输出和等待时间需另外考虑。</td></tr><tr><td><a href="/middleware/redis/plus/subjects/stream-part-02#cmd-xgroup-createconsumer">XGROUP CREATECONSUMER</a></td><td>6.2.0</td><td>O(1)。大值复制、扩容、网络输出和等待时间需另外考虑。</td></tr><tr><td><a href="/middleware/redis/plus/subjects/stream-part-02#cmd-xgroup-delconsumer">XGROUP DELCONSUMER</a></td><td>5.0.0</td><td>官方命令定义标为 O(1)；移除消费者时仍需处理其未完成消息的业务影响。</td></tr><tr><td><a href="/middleware/redis/plus/subjects/stream-part-02#cmd-xgroup-destroy">XGROUP DESTROY</a></td><td>5.0.0</td><td>O(P)，P 为该消费组待处理条目数。</td></tr><tr><td><a href="/middleware/redis/plus/subjects/stream-part-02#cmd-xgroup-setid">XGROUP SETID</a></td><td>5.0.0</td><td>O(1)。大值复制、扩容、网络输出和等待时间需另外考虑。</td></tr><tr><td><a href="/middleware/redis/plus/subjects/stream-part-02#cmd-xgroup-help">XGROUP HELP</a></td><td>5.0.0</td><td>O(1)。</td></tr><tr><td><a href="/middleware/redis/plus/subjects/stream-part-02#cmd-xinfo">XINFO</a></td><td>5.0.0</td><td>取决于所调用的子命令，入口本身不能独立执行。</td></tr><tr><td><a href="/middleware/redis/plus/subjects/stream-part-02#cmd-xinfo-stream">XINFO STREAM</a></td><td>5.0.0</td><td>普通概要 O(1)；FULL 模式随展示的流、组和待处理数据量增长。</td></tr><tr><td><a href="/middleware/redis/plus/subjects/stream-part-02#cmd-xinfo-groups">XINFO GROUPS</a></td><td>5.0.0</td><td>O(G)，G 为消费组数量。</td></tr><tr><td><a href="/middleware/redis/plus/subjects/stream-part-02#cmd-xinfo-consumers">XINFO CONSUMERS</a></td><td>5.0.0</td><td>O(C)，C 为组内消费者数量。</td></tr><tr><td><a href="/middleware/redis/plus/subjects/stream-part-02#cmd-xinfo-help">XINFO HELP</a></td><td>5.0.0</td><td>O(1)。</td></tr><tr><td><a href="/middleware/redis/plus/subjects/stream-part-02#cmd-xsetid">XSETID</a></td><td>5.0.0</td><td>O(1)。大值复制、扩容、网络输出和等待时间需另外考虑。</td></tr></tbody></table></details><p>通用键操作见<a href="/middleware/redis/base/basic/keys">键与过期时间</a>，这里集中列出类型自身的命令。</p>`,16)])])}const h=t(s,[["render",n]]);export{b as __pageData,h as default};
